INSERT INTO iam.roles(code, description) VALUES ('AUDITOR', 'Ejecuta cargas, reglas de análisis, gestiona hallazgos y redacta informes.') ON CONFLICT (code) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO iam.roles(code, description) VALUES ('CONTRALOR', 'Aprueba y firma dictámenes, cierra hallazgos, configura reglas y supervisa el audit trail.') ON CONFLICT (code) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO iam.roles(code, description) VALUES ('SYS_ADMIN', 'Administra plataforma, usuarios, respaldos y salud. Sin acceso a datos de negocio.') ON CONFLICT (code) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO iam.roles(code, description) VALUES ('GERENCIA', 'Consulta indicadores ejecutivos e informes aprobados y firmados (solo lectura).') ON CONFLICT (code) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO iam.roles(code, description) VALUES ('AUDITOR_FINANCIERO', 'Auditor: ejecuta auditorías operativas, especiales, administrativas y financieras, sus cédulas, evidencias e informes en borrador.') ON CONFLICT (code) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO iam.roles(code, description) VALUES ('JEFE_AUDITORIA_FINANCIERA', 'Jefe de Auditoría: supervisa y coordina las auditorías operativas, especiales, administrativas y financieras; no aprueba ni firma como Contralor o Gerente.') ON CONFLICT (code) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO iam.roles(code, description) VALUES ('AUDITOR_SISTEMAS', 'Ejecuta auditorías de sistemas/TI, sus evidencias e informes en borrador, con alcance exclusivo de sistemas.') ON CONFLICT (code) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO iam.roles(code, description) VALUES ('JEFE_AUDITORIA_SISTEMAS', 'Supervisa y coordina auditorías de sistemas/TI, con alcance exclusivo de sistemas; no aprueba ni firma como Contralor o Gerente.') ON CONFLICT (code) DO UPDATE SET description = EXCLUDED.description;
